import { HARNESS_CALLBACK_ID } from "./constants.ts";
import { jsStringLiteral } from "./js.ts";

const HEADER = `\
// Generated by rhino-local AIC lane. Records observed nodeState.
// Comparison against the case happens in verdict.ts, not here.
`;

const HELPERS = `\
function __rhinoLocalKeys(ns) {
  var raw = ns.keys();
  var out = [];
  var i;
  var it;
  var k;
  if (raw === null || raw === undefined) {
    return out;
  }
  if (typeof raw.length === "number" && typeof raw !== "string") {
    for (i = 0; i < raw.length; i += 1) {
      out.push(String(raw[i]));
    }
    return out;
  }
  if (typeof raw.toArray === "function") {
    raw = raw.toArray();
    for (i = 0; i < raw.length; i += 1) {
      out.push(String(raw[i]));
    }
    return out;
  }
  if (typeof raw.iterator === "function") {
    it = raw.iterator();
    while (it.hasNext()) {
      out.push(String(it.next()));
    }
    return out;
  }
  if (typeof raw.size === "function" && typeof raw.get === "function" && typeof raw.keySet !== "function") {
    for (i = 0; i < raw.size(); i += 1) {
      out.push(String(raw.get(i)));
    }
    return out;
  }
  for (k in raw) {
    if (Object.prototype.hasOwnProperty.call(raw, k) && typeof raw[k] !== "function") {
      out.push(String(raw[k]));
    }
  }
  return out;
}

function __rhinoLocalValue(value) {
  var t;
  var i;
  var k;
  var out;
  var keys;
  var arr;
  if (value === null || value === undefined) {
    return null;
  }
  t = typeof value;
  if (t === "string" || t === "number" || t === "boolean") {
    return value;
  }
  if (typeof Array.isArray === "function" && Array.isArray(value)) {
    out = [];
    for (i = 0; i < value.length; i += 1) {
      out.push(__rhinoLocalValue(value[i]));
    }
    return out;
  }
  if (typeof value.keySet === "function" && typeof value.get === "function") {
    out = {};
    keys = value.keySet();
    if (typeof keys.toArray === "function") {
      arr = keys.toArray();
      for (i = 0; i < arr.length; i += 1) {
        out[String(arr[i])] = __rhinoLocalValue(value.get(arr[i]));
      }
      return out;
    }
  }
  if (typeof value.size === "function" && typeof value.get === "function") {
    out = [];
    for (i = 0; i < value.size(); i += 1) {
      out.push(__rhinoLocalValue(value.get(i)));
    }
    return out;
  }
  if (t === "object") {
    out = {};
    for (k in value) {
      if (Object.prototype.hasOwnProperty.call(value, k) && typeof value[k] !== "function") {
        out[String(k)] = __rhinoLocalValue(value[k]);
      }
    }
    return out;
  }
  return String(value);
}

function __rhinoLocalDump(outcome) {
  var keys = __rhinoLocalKeys(nodeState);
  var finalState = {};
  var i;
  var key;
  for (i = 0; i < keys.length; i += 1) {
    key = keys[i];
    finalState[key] = __rhinoLocalValue(nodeState.get(key));
  }
  return { outcome: outcome, final: finalState };
}
`;

/**
 * Next-gen scripted-decision source that dumps final `nodeState` into a
 * HiddenValueCallback. `outcome` is baked in because the tree routes each
 * subject-node outcome to a dedicated result node — the result script cannot
 * see which connection brought it here.
 *
 * Does not compare against `expect`. The runner builds `RecordedEffects`
 * from the dump; `judge()` in verdict.ts is the only pass/fail implementation.
 */
export function emitResultScript(outcome: string): string {
  const idLit = jsStringLiteral(HARNESS_CALLBACK_ID);
  const outcomeLit = jsStringLiteral(outcome);
  return [
    HEADER,
    HELPERS,
    `var __rhinoLocalOutcome = ${outcomeLit};`,
    `var __rhinoLocalPayload = JSON.stringify(__rhinoLocalDump(__rhinoLocalOutcome));`,
    `if (callbacks.isEmpty()) {`,
    `  callbacksBuilder.hiddenValueCallback(${idLit}, __rhinoLocalPayload);`,
    `}`,
    ``,
  ].join("\n");
}
